<?php
use Chengyu\Core\HttpClient;
use Chengyu\Services\{OAuth,Auth,Membership,Payment,Wallet};
function response15(array $body): string {$json=json_encode($body,JSON_THROW_ON_ERROR);return "HTTP/1.1 200 OK\r\nContent-Length: ".strlen($json)."\r\n\r\n".$json;}
function oauth15(string $subject='test-identity',string $provider='google'): array {
    global $a;$_SESSION=[];$_SERVER['REMOTE_ADDR']='oauth-fixture-'.key32();
    settings('connections',['social_enabled'=>'1','oauth_'.$provider.'_enabled'=>'1','oauth_'.$provider.'_id'=>'local-test-app','oauth_'.$provider.'_secret'=>'fixture-client-secret']);
    $auth=new Auth($a->db,$a->settings,$a->crypto,$a->activity,$a->wallet,$a->secondFactor);
    $calls=new ArrayObject();
    $http=new HttpClient(static function($method,$url,$headers,$body)use($subject,$provider,$calls){
        $calls[]=['method'=>$method,'url'=>$url,'headers'=>$headers,'body'=>$body];
        if($method==='POST'){parse_str($body,$fields);truth(isset($fields['code_verifier']));truth(strlen($fields['code_verifier'])>=43);if($provider==='microsoft'){same('https://graph.microsoft.com/User.Read',$fields['scope']);}return response15(['token_type'=>'Bearer','access_token'=>'fixture-access-token']);}
        same('Bearer fixture-access-token',$headers['Authorization']);
        return response15(['sub'=>$subject,'id'=>$subject,'name'=>'Fixture Person','login'=>'FixtureGit','displayName'=>'Fixture Office','email'=>'never-used@example.test']);
    });
    return [new OAuth($a->db,$a->settings,$a->crypto,$a->activity,$a->wallet,$auth,$a->secondFactor,$a->config['url'],$http),$auth,$calls];
}
function callback15(OAuth $oauth,string $provider='google',string $purpose='login',string $password='',string $factor=''): array {
    $url=$oauth->begin($provider,$purpose,$password,$factor);parse_str(parse_url($url,PHP_URL_QUERY),$query);
    $target=$oauth->callback($provider,['state'=>$query['state'],'code'=>'fixture-authorization-code']);return [$query,$target];
}
foreach(['127.0.0.1','10.1.1.1','172.16.0.1','192.168.1.1','169.254.169.254','100.64.0.1','198.18.0.1','192.0.2.1','198.51.100.1','203.0.113.1','0.0.0.0','224.0.0.1','::1','fc00::1','fe80::1','::ffff:8.8.8.8','2001:db8::1','2002:0808:0808::1'] as $ip){test('015: HTTPS transport rejects non-global address '.$ip,static function()use($ip){same(false,HttpClient::publicIp($ip));});}
