foreach(['google','github','microsoft'] as $provider){test('015: '.$provider.' code exchange binds stable subject with PKCE and no token storage',static function()use($a,$provider){[$oauth,$auth,$calls]=oauth15(key32(),$provider);$id=user14('provider');$auth->login(account($id)['username'],'TestPassword!2026');[$q,$target]=callback15($oauth,$provider,'link','TestPassword!2026');same('security',$target);same('S256',$q['code_challenge_method']);same($oauth->callbackUrl($provider),$q['redirect_uri']);same(2,count($calls));same(1,count($oauth->links($id)));$json=json_encode($a->db->one('SELECT * FROM cy_identities WHERE user_id=?',[$id]));truth(strpos($json,'fixture-access-token')===false);truth(strpos($json,'never-used@example.test')===false);$auth->logout();callback15($oauth,$provider);$pending=$oauth->pending();same('login',$pending['kind']);$oauth->login($pending['nonce'],'');same($id,(int)$auth->user()['id']);reject(static function()use($oauth,$pending){$oauth->login($pending['nonce'],'');},403);$auth->logout();});}
