test('015: expired OAuth state never calls provider',static function(){[$oauth,$auth,$calls]=oauth15();$url=$oauth->begin('google','login');parse_str(parse_url($url,PHP_URL_QUERY),$q);$_SESSION['oauth_flows'][$q['state']]['expires_at']=time()-1;reject(static function()use($oauth,$q){$oauth->callback('google',['state'=>$q['state'],'code'=>'x']);},403);same(0,count($calls));});
test('015: provider mismatch consumes but does not exchange state',static function(){[$oauth,$auth,$calls]=oauth15();$url=$oauth->begin('google','login');parse_str(parse_url($url,PHP_URL_QUERY),$q);reject(static function()use($oauth,$q){$oauth->callback('github',['state'=>$q['state'],'code'=>'x']);},403);same(0,count($calls));});
