test('015: external registration follows invitation and local password rules',static function()use($a,$admin){[$oauth,$auth]=oauth15(key32());callback15($oauth);$p=$oauth->pending();settings('users',['registration_mode'=>'invite']);try{$name='conn'.substr(key32(),0,8);$input=['username'=>$name,'email'=>$name.'@example.test','password'=>'TestPassword!2026','display_name'=>'Connected member','agree'=>'1'];reject(static function()use($oauth,$p,$input){$oauth->register($p['nonce'],$input);});same(0,(int)$a->db->value('SELECT COUNT(*) FROM cy_users WHERE username=?',[$name]));$codes=$a->invitations->issue($admin,1,1,time()+3600,'external test');$input['invitation']=$codes[0];$id=$oauth->register($p['nonce'],$input);same(1,count($oauth->links($id)));truth(password_verify('TestPassword!2026',account($id)['password_hash']));same($id,(int)$auth->user()['id']);$auth->logout();}finally{settings('users',['registration_mode'=>'open']);}});
function payment15(array $changes=[],?callable $during=null): array {
 global $a;$_SERVER['REMOTE_ADDR']='payment-fixture-'.key32();settings('epay',['epay_enabled'=>'1','epay_endpoint'=>'https://merchant.example.test/submit.php','epay_merchant'=>'10015','epay_secret'=>'old-query-secret','epay_query_enabled'=>'1','epay_query_endpoint'=>'https://merchant.example.test/api.php','epay_alipay'=>'1']);
 $id=user14('reconcile');$order=$a->payment->create($id,100,'epay','alipay',key32());$calls=new ArrayObject();
 $http=new HttpClient(static function($method,$url,$headers,$body)use($order,$changes,$calls,$during){parse_str(parse_url($url,PHP_URL_QUERY),$q);$calls[]=$q;same('10015',$q['pid']);same('old-query-secret',$q['key']);if($during){$during($order);}return response15(array_merge(['code'=>1,'pid'=>'10015','out_trade_no'=>$order['order_no'],'trade_no'=>'RECEIPT-'.$order['id'],'money'=>'1.00','status'=>1,'type'=>'alipay'],$changes));});
 return [new Payment($a->db,$a->settings,$a->crypto,$a->wallet,$a->activity,$a->config['url'],$http),$id,$order,$calls];
}
