test('015: handoff preserves complete signed URL without exposing it as a form action',static function(){
    $url='https://merchant.example.test/checkout?state=abc&sign=def';
    $data=\Chengyu\Core\ExternalNavigation::target($url);same($url,$data['target']);same('merchant.example.test',$data['host']);
    ob_start();partial('external_handoff',$data+['title'=>'Continue securely']);$html=ob_get_clean();
    truth(strpos($html,'data-external-handoff')!==false);truth(strpos($html,'rel="noreferrer noopener"')!==false);
    truth(strpos($html,'<form')===false);truth(strpos($html,'state=abc&amp;sign=def')!==false);
});
